Theorem asan_imemcpy : forall mem0 (dst src : word) n bs rom regs (ret : word),
  cpyH Asan.M.loaded_segments mem0 dst src n bs ->
  ret_ok ret -> getr regs 1 = ret ->
  getr regs 10 = dst -> getr regs 11 = src -> getr regs 12 = Z_to_bv 64 n ->
