  Lemma b1_run : forall regs (ret : word) k,
    ret_ok ret -> getr regs 1 = ret ->
    getr regs 11 = at_ src k -> getr regs 13 = at_ dst k ->
    (0 <= k)%Z -> (k + 1 = n)%Z ->
    exists regs',
      msteps ASEGS0 (mkst regs (0x149160 : word) (MK k) rom) (mkst regs' ret (MK n) rom)
      /\ keeps regs regs'.
Proof.
