                (fetch_lit _ _ _ _ eq_refl F_137288) (fetch_lit _ _ _ _ eq_refl F_13728c) (fetch_lit _ _ _ _ eq_refl F_137290)
                (fetch_lit _ _ _ _ eq_refl F_137294) (fetch_lit _ _ _ _ eq_refl F_137298)
