(* [comment removed for export] *)
Definition art_ann_lo (b u u' : Z) : Z := b + Z.min u u'.
Definition art_ann_n (u u' : Z) : Z := Z.abs (u - u').
Definition art_ann_v (u u' : Z) : Z := if u <? u' then 0 else 252.

