  0 <= b -> b + c < 2 ^ 47 -> 0 <= u <= c -> 0 <= u' <= c -> b mod 8 = 0 -> u' < u -> RU u' < RU u ->
  exists regs', msteps ASEGS (mkst regs (0x82ae4 : word) M rom) (mkst regs' (0x81a60 : word) M rom)
    /\ getr regs' 1 = Z_to_bv 64 0x82bec /\ getr regs' 10 = Z_to_bv 64 (b + RU u') /\ getr regs' 11 = Z_to_bv 64 (RU u - RU u') /\ getr regs' 12 = Z_to_bv 64 252
    /\ getr regs' 9 = Z_to_bv 64 (b + RD u') /\ getr regs' 18 = Z_to_bv 64 (b + RU u')
    /\ (forall r : reg, r <> 1%bv -> r <> 9%bv -> r <> 10%bv -> r <> 11%bv -> r <> 12%bv -> r <> 18%bv -> getr regs' r = getr regs r).
Proof.
