Definition axmap (e : bool) : axv := if e then AXc else AX0.

Lemma atexit_cells_of_st M e : PQSTA.atexit_stA RSEGS AD AAD AQ M e -> atexit_cellsA M (axmap e).
Proof.
  unfold PQSTA.atexit_stA, HAJ.atexit_cells.
  cbn [pa_atexit paa_atexit_f0 paa_atexit_a0 paa_at_cxa_atexit qa_drv_call qa_drv_guard pa_errcat_dtor pa_errcat_obj AD AAD AQ ADDR_A AADDR_A QADDR_A].
  unfold atexit_cellsA, AX_CELLS, ax_cell, axmap.
  destruct e; cbn [PQSTA.ax_list length Z.of_nat Z.mul Z.add Pos.of_succ_nat Pos.mul Pos.add Pos.succ];
    intros (_ & C4 & C8 & C16 & C24 & C32 & C288 & C40 & C296 & EXT).
  - destruct (EXT 0%nat _ _ eq_refl) as (E1 & E2 & E3 & E4). cbn [Z.of_nat Z.mul Z.add] in E1, E2, E3, E4.
    repeat apply Forall_cons; cbn [fst snd Z.to_nat Pos.to_nat Pos.iter_op Nat.add]; try apply Forall_nil; assumption.
  - repeat apply Forall_cons; cbn [fst snd Z.to_nat Pos.to_nat Pos.iter_op Nat.add]; try apply Forall_nil; assumption.
Qed.

