Theorem lsx_atexit : forall (g : PMST.st) (M : word -> option byte),
  LibIface.ls_ok (PQSTA.TopLSA RSEGS AD AAD AQ) g M -> exists ax : axv, atexit_cellsA M ax.
Proof.
